  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --color-primary: oklch(12% 0.02 265);
      --color-accent: oklch(55% 0.22 235);
      --color-accent-hover: oklch(50% 0.25 235);
      --color-bg: oklch(98% 0.01 265);
      --color-surface: oklch(100% 0 0);
      --color-border: oklch(92% 0.01 265);
      --color-text-secondary: oklch(45% 0.02 265);
      --color-tag-bg: oklch(96% 0.01 265);
      --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.04);
      --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.08);
      --shadow-lg: 0 8px 24px oklch(0% 0 0 / 0.12);
      --transition-fast: 150ms ease;
      --transition-normal: 250ms ease;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font-family);
      background: var(--color-bg);
      color: var(--color-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    /* Header */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--color-surface);
      border-bottom: 1px solid var(--color-border);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .header-left {
      display: flex;
      align-items: center;
      gap: 40px;
    }

    .logo {
      font-weight: 800;
      font-size: 20px;
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--color-accent);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 16px;
      height: 16px;
      fill: white;
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .nav-item {
      position: relative;
    }

    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 12px;
      font-size: 14px;
      font-weight: 500;
      color: var(--color-text-secondary);
      border-radius: var(--radius-sm);
      transition: all var(--transition-fast);
      cursor: pointer;
    }

    .nav-link:hover {
      color: var(--color-primary);
      background: var(--color-tag-bg);
    }

    .nav-link svg {
      width: 14px;
      height: 14px;
      opacity: 0.6;
    }

    .nav-link-arrow {
      transition: transform var(--transition-fast);
    }

    .nav-item:hover .nav-link-arrow {
      transform: rotate(180deg);
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      min-width: 600px;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-fast);
    }

    .nav-item:hover .mega-menu {
      opacity: 1;
      visibility: visible;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .mega-menu-section h4 {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--color-text-secondary);
      margin-bottom: 12px;
    }

    .mega-menu-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mega-menu-list a {
      display: block;
      font-size: 13px;
      color: var(--color-primary);
      padding: 4px 0;
      transition: color var(--transition-fast);
    }

    .mega-menu-list a:hover {
      color: var(--color-accent);
    }

    .mega-menu-list li:first-child a {
      font-weight: 600;
    }

    .mega-menu-desc {
      font-size: 12px;
      color: var(--color-text-secondary);
      margin-top: -4px;
    }

    /* Header Right */
    .header-right {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      font-size: 14px;
      font-weight: 500;
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      border: none;
      cursor: pointer;
      transition: all var(--transition-fast);
    }

    .btn-ghost {
      background: transparent;
      color: var(--color-text-secondary);
    }

    .btn-ghost:hover {
      background: var(--color-tag-bg);
      color: var(--color-primary);
    }

    .btn-primary {
      background: var(--color-accent);
      color: white;
    }

    .btn-primary:hover {
      background: var(--color-accent-hover);
    }

    /* Main Content */
    .main {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Hero Section */
    .hero {
      text-align: center;
      padding: 80px 0 48px;
    }

    .hero h1 {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      letter-spacing: -1.5px;
      line-height: 1.1;
      margin-bottom: 16px;
    }

    .hero p {
      font-size: 18px;
      color: var(--color-text-secondary);
      max-width: 560px;
      margin: 0 auto;
    }

    /* Category Filters */
    .filters-section {
      padding: 0 0 48px;
    }

    .filters-wrapper {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
    }

    .category-filters {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .filter-pill {
      display: inline-flex;
      align-items: center;
      padding: 8px 16px;
      font-size: 13px;
      font-weight: 500;
      border: 1px solid var(--color-border);
      border-radius: 100px;
      background: var(--color-surface);
      color: var(--color-text-secondary);
      cursor: pointer;
      transition: all var(--transition-fast);
    }

    .filter-pill:hover {
      border-color: var(--color-primary);
      color: var(--color-primary);
    }

    .filter-pill.active {
      background: var(--color-primary);
      border-color: var(--color-primary);
      color: white;
    }

    .search-wrapper {
      position: relative;
    }

    .search-input {
      width: 240px;
      padding: 10px 16px 10px 40px;
      font-size: 14px;
      font-family: inherit;
      border: 1px solid var(--color-border);
      border-radius: 100px;
      background: var(--color-surface);
      color: var(--color-primary);
      transition: all var(--transition-fast);
    }

    .search-input::placeholder {
      color: var(--color-text-secondary);
    }

    .search-input:focus {
      outline: none;
      border-color: var(--color-accent);
      box-shadow: 0 0 0 3px oklch(55% 0.22 235 / 0.15);
    }

    .search-icon {
      position: absolute;
      left: 14px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--color-text-secondary);
    }

    /* Featured Articles */
    .featured-section {
      padding-bottom: 64px;
    }

    .section-label {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--color-text-secondary);
      margin-bottom: 24px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .featured-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition-normal);
      display: flex;
      flex-direction: column;
    }

    .featured-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .featured-card:first-child {
      grid-column: span 2;
    }

    .featured-card-image {
      height: 200px;
      background: linear-gradient(135deg, oklch(55% 0.22 235) 0%, oklch(65% 0.18 265) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .featured-card:first-child .featured-card-image {
      height: 280px;
    }

    .featured-card-image svg {
      width: 64px;
      height: 64px;
      fill: white;
      opacity: 0.3;
    }

    .featured-stats {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 16px;
      background: linear-gradient(to top, oklch(0% 0 0 / 0.7), transparent);
      display: flex;
      gap: 24px;
    }

    .stat {
      color: white;
    }

    .stat-value {
      font-size: 20px;
      font-weight: 700;
    }

    .stat-label {
      font-size: 11px;
      opacity: 0.8;
    }

    .featured-card-content {
      padding: 24px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .card-meta {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 12px;
    }

    .card-date {
      font-size: 13px;
      color: var(--color-text-secondary);
    }

    .card-tag {
      display: inline-block;
      padding: 4px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.3px;
      background: var(--color-tag-bg);
      color: var(--color-text-secondary);
      border-radius: 100px;
    }

    .featured-card h3 {
      font-size: 20px;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
      letter-spacing: -0.3px;
    }

    .featured-card:first-child h3 {
      font-size: 28px;
    }

    .featured-card p {
      font-size: 14px;
      color: var(--color-text-secondary);
      line-height: 1.6;
      flex: 1;
    }

    .card-author {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 20px;
      padding-top: 20px;
      border-top: 1px solid var(--color-border);
    }

    .author-avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--color-accent);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 600;
      color: white;
    }

    .author-name {
      font-size: 13px;
      font-weight: 500;
    }

    /* Latest News */
    .latest-section {
      padding-bottom: 64px;
    }

    .latest-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .latest-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      padding: 24px;
      transition: all var(--transition-normal);
      cursor: pointer;
    }

    .latest-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .latest-card .card-meta {
      margin-bottom: 16px;
    }

    .latest-card h3 {
      font-size: 17px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 10px;
      letter-spacing: -0.2px;
    }

    .latest-card p {
      font-size: 14px;
      color: var(--color-text-secondary);
      line-height: 1.6;
    }

    .latest-card .card-author {
      margin-top: 20px;
      padding-top: 16px;
    }

    /* No Results */
    .no-results {
      grid-column: 1 / -1;
      text-align: center;
      padding: 80px 24px;
    }

    .no-results h3 {
      font-size: 20px;
      margin-bottom: 8px;
    }

    .no-results p {
      color: var(--color-text-secondary);
    }

    /* Show More */
    .show-more-wrapper {
      display: flex;
      justify-content: center;
      padding: 32px 0 64px;
    }

    .btn-show-more {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 12px 24px;
      font-size: 14px;
      font-weight: 500;
      border: 1px solid var(--color-border);
      border-radius: var(--radius-sm);
      background: var(--color-surface);
      color: var(--color-primary);
      cursor: pointer;
      transition: all var(--transition-fast);
    }

    .btn-show-more:hover {
      background: var(--color-primary);
      color: white;
      border-color: var(--color-primary);
    }

    .btn-show-more svg {
      width: 16px;
      height: 16px;
    }

    /* CTA Banner */
    .cta-section {
      padding: 64px 0;
    }

    .cta-banner {
      background: var(--color-primary);
      border-radius: var(--radius-lg);
      padding: 64px;
      text-align: center;
      color: white;
    }

    .cta-banner h2 {
      font-size: 36px;
      font-weight: 800;
      letter-spacing: -1px;
      margin-bottom: 12px;
    }

    .cta-banner p {
      font-size: 18px;
      opacity: 0.8;
      margin-bottom: 32px;
    }

    .cta-buttons {
      display: flex;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .btn-cta-primary {
      background: white;
      color: var(--color-primary);
    }

    .btn-cta-primary:hover {
      background: oklch(98% 0.01 265);
    }

    .btn-cta-secondary {
      background: transparent;
      color: white;
      border: 1px solid rgba(255,255,255,0.3);
    }

    .btn-cta-secondary:hover {
      background: rgba(255,255,255,0.1);
    }

    .cta-enterprise {
      margin-top: 48px;
      padding-top: 48px;
      border-top: 1px solid rgba(255,255,255,0.15);
    }

    .cta-enterprise p {
      font-size: 14px;
      margin-bottom: 16px;
    }

    /* Footer */
    .footer {
      background: var(--color-surface);
      border-top: 1px solid var(--color-border);
      padding: 64px 0 32px;
    }

    .footer-grid {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      display: grid;
      grid-template-columns: 2fr repeat(6, 1fr);
      gap: 48px;
    }

    .footer-brand {
      padding-right: 48px;
    }

    .footer-brand .logo {
      margin-bottom: 16px;
    }

    .footer-brand p {
      font-size: 14px;
      color: var(--color-text-secondary);
      margin-bottom: 24px;
    }

    .footer-status {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      color: var(--color-text-secondary);
    }

    .status-dot {
      width: 8px;
      height: 8px;
      background: #22c55e;
      border-radius: 50%;
    }

    .footer-column h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--color-primary);
      margin-bottom: 16px;
    }

    .footer-column ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-column a {
      font-size: 13px;
      color: var(--color-text-secondary);
      transition: color var(--transition-fast);
    }

    .footer-column a:hover {
      color: var(--color-primary);
    }

    .footer-bottom {
      max-width: 1280px;
      margin: 48px auto 0;
      padding: 24px 24px 0;
      border-top: 1px solid var(--color-border);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .footer-bottom p {
      font-size: 13px;
      color: var(--color-text-secondary);
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      color: var(--color-text-secondary);
      transition: color var(--transition-fast);
    }

    .footer-social a:hover {
      color: var(--color-primary);
    }

    .footer-social svg {
      width: 20px;
      height: 20px;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .featured-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .featured-card:first-child {
        grid-column: span 2;
      }

      .mega-menu-grid {
        min-width: 500px;
      }

      .footer-grid {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    @media (max-width: 768px) {
      .header-left {
        gap: 16px;
      }

      .nav {
        display: none;
      }

      .hero {
        padding: 48px 0 32px;
      }

      .filters-wrapper {
        flex-direction: column;
        align-items: stretch;
      }

      .category-filters {
        justify-content: flex-start;
        overflow-x: auto;
        flex-wrap: nowrap;
        padding-bottom: 8px;
      }

      .filter-pill {
        flex-shrink: 0;
      }

      .search-input {
        width: 100%;
      }

      .featured-grid {
        grid-template-columns: 1fr;
      }

      .featured-card:first-child {
        grid-column: span 1;
      }

      .latest-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 32px;
      }

      .footer-brand {
        grid-column: span 2;
        padding-right: 0;
      }

      .cta-banner {
        padding: 40px 24px;
      }

      .cta-banner h2 {
        font-size: 28px;
      }
    }

    @media (max-width: 480px) {
      .latest-grid {
        grid-template-columns: 1fr;
      }

      .footer-grid {
        grid-template-columns: 1fr;
      }

      .footer-brand {
        grid-column: span 1;
      }

      .footer-bottom {
        flex-direction: column;
        gap: 16px;
        text-align: center;
      }
    }
  </style>
</head>
